export interface RegexTraceEvent {
  readonly type: "dfa_cache_hit" | "dfa_cache_miss" | "dfa_state_evicted" | "pike_vm_fallback";
  readonly stateId?: number;
  readonly position?: number;
  readonly count?: number;
}

export interface CompileOptions {
  readonly maxDfaStates?: number;
  readonly maxDepth?: number;
  readonly maxPatternLength?: number;
  readonly onEvent?: (event: RegexTraceEvent) => void;
}

export interface EngineStats {
  readonly steps: number;
  readonly engine: "dfa" | "pike";
}

export interface RegexMatch {
  readonly match: string;
  readonly index: number;
  readonly length: number;
  readonly captures: readonly (string | undefined)[];
  readonly groups: Readonly<Record<string, string | undefined>>;
}

export declare abstract class LinearRegexError extends Error {
  readonly code: string;
  constructor(message: string, code: string);
}

export declare class UnsupportedFeatureError extends LinearRegexError {
  readonly code: "UNSUPPORTED_FEATURE";
  constructor(message: string);
}

export declare class RegexSyntaxError extends LinearRegexError {
  readonly code: "PARSE_ERROR";
  readonly position: number;
  constructor(message: string, position: number);
}

export declare class LimitExceededError extends LinearRegexError {
  readonly code: "LIMIT_EXCEEDED";
  constructor(message: string);
}

import type { CompileOptions } from "./types";

export interface FlagSet {
  readonly caseInsensitive: boolean;
  readonly multiline: boolean;
  readonly dotAll: boolean;
  readonly ungreedy: boolean;
}

export type AstNode =
  | { readonly type: "literal"; readonly codePoint: number }
  | { readonly type: "dot" }
  | {
      readonly type: "charClass";
      readonly ranges: readonly (readonly [number, number])[];
      readonly inverted: boolean;
    }
  | {
      readonly type: "anchor";
      readonly kind:
        | "start_line"
        | "end_line"
        | "start_text"
        | "end_text"
        | "word_boundary"
        | "not_word_boundary";
    }
  | {
      readonly type: "repetition";
      readonly child: AstNode;
      readonly min: number;
      readonly max: number;
      readonly greedy: boolean;
    }
  | { readonly type: "concat"; readonly children: readonly AstNode[] }
  | { readonly type: "alt"; readonly children: readonly AstNode[] }
  | {
      readonly type: "group";
      readonly child: AstNode;
      readonly capturing: boolean;
      readonly index?: number;
      readonly name?: string;
    };

export interface AstRoot {
  readonly root: AstNode;
  readonly flags: FlagSet;
  readonly captureCount: number;
  readonly groupNames: ReadonlyMap<string, number>;
}

export declare function parseRegex(
  pattern: string,
  flags?: string,
  options?: CompileOptions,
): AstRoot;

import type { AstRoot } from "./ast";

export interface NfaTransition {
  readonly fromState: number;
  readonly toState: number;
  readonly kind: "epsilon" | "range" | "anchor";
  readonly min?: number;
  readonly max?: number;
  readonly anchorKind?:
    | "start_line"
    | "end_line"
    | "start_text"
    | "end_text"
    | "word_boundary"
    | "not_word_boundary";
  readonly captureSlot?: number;
}

export interface NfaGraph {
  readonly startState: number;
  readonly matchState: number;
  readonly stateCount: number;
  readonly captureCount: number;
  readonly groupNames: ReadonlyMap<string, number>;
  readonly transitionsFrom: (state: number) => readonly NfaTransition[];
}

export declare function buildNfa(ast: AstRoot): NfaGraph;

import type { NfaGraph } from "./nfa";
import type { CompileOptions, EngineStats, RegexMatch } from "./types";

export interface ExecutionResult {
  readonly match: RegexMatch | null;
  readonly matched: boolean;
  readonly stats: EngineStats;
}

export interface EngineExecutor {
  test(
    input: string,
    startIndex?: number,
  ): { readonly matched: boolean; readonly stats: EngineStats };
  exec(input: string, startIndex?: number): ExecutionResult;
}

export declare function createExecutor(nfa: NfaGraph, options?: CompileOptions): EngineExecutor;

import type { CompileOptions, RegexMatch } from "./types";

export interface LinearRegex {
  test(input: string): boolean;
  exec(input: string): RegexMatch | null;
  matchAll(input: string): IterableIterator<RegexMatch>;
  replace(input: string, replacement: string | ((match: RegexMatch) => string)): string;
  lastStats(): { steps: number; engine: "dfa" | "pike" };
}

export declare function compile(
  pattern: string,
  flags?: string,
  options?: CompileOptions,
): LinearRegex;
export declare function replace(
  input: string,
  replacement: string | ((match: RegexMatch) => string),
  pattern: string,
  flags?: string,
  options?: CompileOptions,
): string;
